#!/usr/bin/env python3
# 119_remap_angle_changes.py
# v1.0 (2025-08-28)
# Purpose: Remaps the 'absolute_cut_time' in AI pacing plans (*_changes.json)
# from the original source media's timeline to the new "clean takes" timeline.
#
# How it works:
# 1. Reads the 'timecode_map.json' generated by 115_timeline_builder.py.
# 2. Finds all '*_changes.json' files in the specified pacing plans directory.
# 3. For each file, it remaps the 'absolute_cut_time' for every proposed cut
#    using the timecode map.
# 4. Saves a new file with the suffix '_remapped.json' containing the corrected data.

import json
import argparse
from pathlib import Path
from typing import List, Dict, Any, Optional

def find_segment_for_time(time_map: List[Dict[str, float]], source_time: float) -> Optional[Dict[str, float]]:
    """Finds the time map segment that contains the given source time."""
    for segment in time_map:
        if segment['source_start'] - 0.01 <= source_time <= segment['source_end'] + 0.01:
            return segment
    return None

def remap_angle_files(map_path: Path, plans_dir: Path):
    """
    Remaps timestamps in all *_changes.json files within a directory.
    """
    if not map_path.exists():
        raise FileNotFoundError(f"Timecode map not found at: {map_path}")
    if not plans_dir.is_dir():
        raise FileNotFoundError(f"Pacing plans directory not found at: {plans_dir}")

    print(f"-> Loading timecode map from: {map_path}")
    with open(map_path, 'r', encoding='utf-8') as f:
        time_map = json.load(f)

    change_files = list(plans_dir.glob("*_changes.json"))
    if not change_files:
        print("-> No '*_changes.json' files found to remap. Exiting.")
        return

    print(f"-> Found {len(change_files)} angle change plan(s) to process.")

    for plan_file in change_files:
        print(f"\n--- Processing: {plan_file.name} ---")
        with open(plan_file, 'r', encoding='utf-8') as f:
            plan_data = json.load(f)

        remapped_count = 0
        for change in plan_data.get("angle_changes", []):
            source_cut_time = change.get("absolute_cut_time")
            if source_cut_time is None:
                continue

            segment = find_segment_for_time(time_map, source_cut_time)

            if segment:
                time_in_segment = source_cut_time - segment['source_start']
                new_cut_time = segment['timeline_start'] + time_in_segment
                change['remapped_cut_time'] = new_cut_time
                remapped_count += 1
                print(f"  - Mapped source time {source_cut_time:.2f}s -> new timeline time {new_cut_time:.2f}s")
            else:
                change['remapped_cut_time'] = None # Flag that it couldn't be mapped
                print(f"  - WARNING: Could not map source time {source_cut_time:.2f}s. It may fall in a deleted segment.")

        output_path = plan_file.parent / f"{plan_file.stem}_remapped.json"
        with open(output_path, 'w', encoding='utf-8') as f:
            json.dump(plan_data, f, indent=2)
        print(f"-> Saved remapped plan to: {output_path.name}")

    print("\n[+] Remapping of all angle plans complete.")

def main():
    parser = argparse.ArgumentParser(
        description="Remap angle change timestamps from source media time to clean timeline time.",
        formatter_class=argparse.RawTextHelpFormatter
    )
    parser.add_argument(
        '--map',
        required=True,
        help="Path to the timecode_map.json file."
    )
    parser.add_argument(
        '--plans-dir',
        required=True,
        help="Path to the directory containing the '*_changes.json' pacing plans."
    )
    args = parser.parse_args()

    try:
        remap_angle_files(Path(args.map), Path(args.plans_dir))
    except (FileNotFoundError, KeyError) as e:
        print(f"\nERROR: {e}")
        exit(1)

if __name__ == "__main__":
    main()